  if (!tip) { tip = document.createElement('div'); tip.id = 'glTip'; tip.setAttribute('role', 'tooltip'); document.body.appendChild(tip); }
  tip.innerHTML = `<b>${esc(g.t)}</b><p>${esc(g.d)}</p>`;
  tip.classList.add('show'); cur = el;
