document.addEventListener('click', e => { const el = e.target.closest && e.target.closest('.gl'); if (el) { e.stopPropagation(); if (cur === el && !hover.matches) hide(); else show(el); return; } if (!(e.target.closest && e.target.closest('#glTip'))) hide(); }, true);
